def find_insert_position(sorted_values, target):
    """Return the index where target should be inserted to keep the list sorted.

    If target is already present, return the index of its FIRST occurrence.
    """
    low = 0
    high = len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

package cache

import (
	"container/list"
)

type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity  int
	items     map[string]*list.Element
	evictList *list.List
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get retrieves a value from the cache. If the key exists, it moves the entry to the front.
func (c *LRU) Get(key string) (int, bool) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		return ent.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache or updates an existing one.
// If the cache is at capacity, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	if c.capacity <= 0 {
		return
	}

	// If the key already exists, update the value and move it to the front.
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		ent.Value.(*entry).value = value
		return
	}

	// If the cache is full, evict the least recently used item.
	if c.evictList.Len() >= c.capacity {
		last := c.evictList.Back()
		if last != nil {
			c.evictList.Remove(last)
			lastEntry := last.Value.(*entry)
			delete(c.items, lastEntry.key)
		}
	}

	// Add the new entry to the front of the list.
	ent := c.evictList.PushFront(&entry{key, value})
	c.items[key] = ent
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return c.evictList.Len()
}

export function groupConsecutive(values: number[]): number[][] {
  if (values.length === 0) {
    return [];
  }

  const result: number[][] = [];
  let currentRun: number[] = [values[0]];

  for (let i = 1; i < values.length; i++) {
    if (values[i] === values[i - 1] + 1) {
      currentRun.push(values[i]);
    } else {
      result.push(currentRun);
      currentRun = [values[i]];
    }
  }

  result.push(currentRun);
  return result;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
// Rewrite this to use async/await and a plain loop. Behaviour must not change,
// including that a cycle throws Error("cycle detected") and that the chain is
// capped at 50 entries with Error("chain too long").
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let currentId = start;

  while (true) {
    if (seen.has(currentId)) {
      throw new Error("cycle detected");
    }
    seen.add(currentId);
    chain.push(currentId);
    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(currentId);
    if (node.parent === null) {
      return chain;
    }
    currentId = node.parent;
  }
}

using UnityEngine;
using System.Collections.Generic;

public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int prewarmCount;

    private Queue<GameObject> pool = new Queue<GameObject>();
    private HashSet<GameObject> activeObjects = new HashSet<GameObject>();

    private void Awake()
    {
        for (int i = 0; i < prewarmCount; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            pool.Enqueue(obj);
        }
    }

    public GameObject Rent()
    {
        GameObject obj;

        if (pool.Count > 0)
        {
            obj = pool.Dequeue();
        }
        else
        {
            obj = Instantiate(prefab, transform);
        }

        obj.SetActive(true);
        activeObjects.Add(obj);
        return obj;
    }

    public void Return(GameObject go)
    {
        if (go == null)
        {
            return;
        }

        // If the object is in the active set, remove it and return it to the pool.
        // If it's already in the pool (not in the active set), Remove returns false,
        // preventing the same object from being added to the queue twice.
        if (activeObjects.Remove(go))
        {
            go.SetActive(false);
            pool.Enqueue(go);
        }
    }
}

using System;

public class TelemetrySender
{
    private readonly NetworkManager _networkManager;

    public TelemetrySender(NetworkManager networkManager)
    {
        _networkManager = networkManager;
    }

    public void Send(string opcode, string payload)
    {
        string truncatedOpcode = opcode.Length > 8 ? opcode.Substring(0, 8) : opcode;
        string frame = _networkManager.Encode(truncatedOpcode, payload);
        _networkManager.Enqueue(frame);
    }
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int zeroes = 0;
        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                zeroes++;
            }
        }
        return zeroes;
    }
}
